import re

from entpy.framework.descriptor import Descriptor
from entpy.framework.imported_object import ImportedObject

__all__ = ["ImportedObject"]

GENERATED_HEADER = """####################
# Code generated by EntPy - do not modify manually!
####################
"""


def to_snake_case(name: str) -> str:
    return re.sub(r"(?<!^)(?=[A-Z])", "_", name).lower()


def get_description(descriptor: Descriptor) -> str:
    content = descriptor.get_description()
    if content:
        return f'\n    """\n    {content}\n    """'
    return ""
